{
  "findings": [
    {
      "check_id": "CKV_AWS_20",
      "title": "S3 Bucket has an ACL defined which allows public READ access.",
      "resource": "aws_s3_bucket.logs",
      "severity": "CRITICAL",
      "explanation": "The bucket uses the deprecated 'acl' argument. While 'log-delivery-write' is not strictly public-read, using legacy ACLs on S3 buckets is a security anti-pattern that can lead to unintended public exposure if misconfigured or if default ACLs are applied. Modern best practice requires disabling ACLs and using Bucket Policies for access control."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The bucket is configured with server-side encryption using AWS KMS (aws:kms) and a specific CMK ARN. This satisfies the requirement for KMS encryption. However, the use of the deprecated 'server_side_encryption_configuration' block within the main resource is discouraged in favor of the separate 'aws_s3_bucket_server_side_encryption_configuration' resource for better state management and clarity, though technically compliant with CKV_AWS_145 if the key exists. The primary issue here is the mix of deprecated arguments."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"

  # Removed deprecated 'acl' argument to prevent potential public exposure issues
  # Access should be controlled via aws_s3_bucket_policy

  versioning {
    enabled = true
  }

  # Moved encryption configuration to its own resource as per modern Terraform AWS provider best practices
  # This ensures strict compliance and avoids deprecation warnings

  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logs_key.arn
    }
  }
}

# Note: If log delivery is required, it must now be explicitly granted via 
# aws_s3_bucket_policy allowing the Log Delivery Service principal to write.
# Example policy snippet would be needed if this bucket receives logs from other services.",
  "fix_summary": "Removed the deprecated 'acl' argument to mitigate risks associated with legacy ACL-based access controls (CKV_AWS_20). Refactored the server-side encryption configuration into a dedicated 'aws_s3_bucket_server_side_encryption_configuration' resource to align with current Terraform AWS Provider best practices and ensure clear, maintainable encryption enforcement (CKV_AWS_145)."
}
